<script setup lang="ts">
import { computed,h,onMounted,reactive,ref,watch } from 'vue'
import { NAlert,NButton,NDataTable,NDatePicker,NForm,NFormItem,NIcon,NInput,NInputNumber,NModal,NPopconfirm,NSelect,NSwitch,NTag,useMessage } from 'naive-ui'
import { Plus,Refresh } from '@vicons/tabler'
import { api,bytes,stamp } from '../api'
import { initialExpiry,nodeRouting } from '../forms'
import { extendExpiry } from '../calendar'
import type { RouteDraft } from '../forms'
import ProtocolPreset from './ProtocolPreset.vue'
import NodeCertificate from './NodeCertificate.vue'
import ServerNodeCards from './ServerNodeCards.vue'
import {serverCards,moveCard} from '../serverCards'
import {publicHostForConfig} from '../certificates'
import NodeRouting from './NodeRouting.vue'
import UserActions from './UserActions.vue'
import NodeDiagnostics from './NodeDiagnostics.vue'
import { autofillPublicHost,automaticMachineAddress,cycleStamp,machinePublicAddresses,planIDs,toggleActive } from '../featureState'
const props=defineProps<{kind:string;me?:any;zone?:string}>();const message=useMessage()
const names:Record<string,string>={users:'用户',plans:'套餐',nodes:'节点'}
const descriptions:Record<string,string>={users:'管理账号、配额与有效期。',plans:'建立套餐，供新用户分配额度与有效期。',nodes:'选择服务器，配置逻辑节点与落地分流，保存后自动同步。'}
const rows=ref<any[]>([]),plans=ref<any[]>([]),machines=ref<any[]>([]),busy=ref(false),saving=ref(false),show=ref(false),editing=ref<number|null>(null),error=ref(''),formError=ref(''),exits=ref<any[]>([]),defaultExit=ref(0),globalExit=ref(false),routeRules=ref<RouteDraft[]>([])
const form=reactive<any>({}),diagnosticNode=ref<any>(null)
const toggling=ref(new Set<number>())
const deleting=ref(new Set<number>())
const automaticHost=ref('')
const browsingMachine=ref<number|null>(null),cardOrder=ref<number[]>([]),layoutSaving=ref(false)
const cards=computed(()=>serverCards(machines.value,rows.value,cardOrder.value))
const visibleRows=computed(()=>props.kind!=='nodes'?rows.value:rows.value.filter(row=>browsingMachine.value===0?!machines.value.some(m=>m.id===row.machine_id):row.machine_id===browsingMachine.value))
const serverName=computed(()=>browsingMachine.value===0?'待分配服务器':machines.value.find(m=>m.id===browsingMachine.value)?.name||'服务器')
async function reorderCards(from:number,to:number){const previous=cardOrder.value;cardOrder.value=moveCard(cards.value.filter(c=>c.id>0).map(c=>c.id),from,to);layoutSaving.value=true;try{await api('/api/admin/machines/layout',{method:'PUT',body:JSON.stringify({machine_ids:cardOrder.value})})}catch(e){cardOrder.value=previous;message.error((e as Error).message)}finally{layoutSaving.value=false}}
const presetForm=ref<InstanceType<typeof ProtocolPreset>|null>(null),certificateForm=ref<InstanceType<typeof NodeCertificate>|null>(null)
const selectedMachine=computed(()=>machines.value.find(machine=>machine.id===form.machine_id))
const publicAddresses=computed(()=>machinePublicAddresses(selectedMachine.value?.status))
function fillAddress(address:string){form.public_host=address;automaticHost.value=address}
watch(()=>form.machine_id,()=>{if(props.kind!=='nodes')return;const candidate=automaticMachineAddress(selectedMachine.value?.status),current=form.public_host||'',previous=automaticHost.value;form.public_host=autofillPublicHost(current,previous,candidate);automaticHost.value=!current.trim()||(!!previous&&current===previous)?candidate:''})
const kernelType=computed(()=>{try{return JSON.parse(form.config||'{}').kernel_type||'xray'}catch{return ''}})
const usesTunnel=computed(()=>{try{return JSON.parse(form.config||'{}').connector?.kind==='cloudflared'}catch{return false}})
async function load(){busy.value=true;error.value='';try{rows.value=await api('/api/admin/'+props.kind);if(['users','nodes'].includes(props.kind))plans.value=await api('/api/admin/plans');if(props.kind==='nodes')[machines.value,exits.value,cardOrder.value]=await Promise.all([api('/api/admin/machines'),api('/api/admin/exits'),api('/api/admin/machines/layout')])}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function setActive(row:any,value:boolean){if(toggling.value.has(row.id))return;toggling.value.add(row.id);try{await toggleActive(row,value,active=>api(`/api/admin/nodes/${row.id}/active`,{method:'PATCH',body:JSON.stringify({active})}));message.success(value?'节点已启用':'节点已停用')}catch(e){message.error((e as Error).message)}finally{toggling.value.delete(row.id)}}
async function removeNode(row:any){if(deleting.value.has(row.id))return;deleting.value.add(row.id);try{await api(`/api/admin/nodes/${row.id}`,{method:'DELETE'});message.success('节点已删除，历史流量记录保留');await load()}catch(e){message.error((e as Error).message);return false}finally{deleting.value.delete(row.id)}}
async function open(row?:any){
 let config=row?.config,selectedPlans=row?.plan_ids||[]
 if(props.kind==='nodes'){
  try{
   const [availableMachines,availableExits]=await Promise.all([api('/api/admin/machines'),api('/api/admin/exits')]);machines.value=availableMachines;exits.value=availableExits
   if(row){const [nodeConfig,routing]=await Promise.all([api('/api/admin/nodes/'+row.id),api('/api/admin/nodes/'+row.id+'/exits')]);selectedPlans=nodeConfig.plan_ids||selectedPlans;config={...nodeConfig};delete config.plan_ids;defaultExit.value=routing.default_exit??0;globalExit.value=routing.global??defaultExit.value>0;routeRules.value=(routing.rules||[]).map((r:any)=>({exit_id:r.exit_id,domains:(r.domain_suffixes||[]).join('\n'),cidrs:(r.ip_cidrs||[]).join('\n')}))}
   else {defaultExit.value=0;globalExit.value=false;routeRules.value=[]}
  }catch(e){message.error((e as Error).message);return}
 }
 editing.value=row?.id??null;formError.value='';automaticHost.value='';Object.assign(form,{name:row?.name||'',email:row?.email||'',password:'',role:row?.role||'user',plan_id:row?.plan_id??null,plan_ids:selectedPlans,opened_at:row?.opened_at,next_reset_at:row?.next_reset_at,inviter_id:row?.inviter_id,quota_gib:(row?.quota_bytes??50*1073741824)/1073741824,expiry:initialExpiry(row?.expires_at,!!row),active:row?.active??true,days:row?.duration_days??30,price:(row?.price_cents??0)/100,machine_id:row?.machine_id??(browsingMachine.value||null),multiplier:(row?.multiplier_milli??1000)/1000,interval:row?.report_interval??60,public_host:row?.public_host||'',config:JSON.stringify(config||{protocol:'vless',listen_ip:'0.0.0.0',server_port:443,network:'tcp',tls:0,kernel_type:'xray'},null,2)});show.value=true}
async function save(){saving.value=true;formError.value='';try{let body:any
 if(props.kind==='users'){body=editing.value?{active:form.active,quota_bytes:Math.round(form.quota_gib*1073741824),expires_at:form.expiry?new Date(form.expiry).toISOString():null,...(form.password?{password:form.password}:{})}:{email:form.email,password:form.password,role:form.role,plan_id:form.plan_id,quota_bytes:Math.round(form.quota_gib*1073741824),expires_at:form.expiry?new Date(form.expiry).toISOString():null}}
 else if(props.kind==='plans')body={name:form.name,quota_bytes:Math.round(form.quota_gib*1073741824),duration_days:form.days,price_cents:Math.round(form.price*100)}
 else if(props.kind==='nodes'){if(!Number.isSafeInteger(form.machine_id)||form.machine_id<=0)throw new Error('请选择归属服务器。');body={name:form.name,machine_id:form.machine_id,...(!editing.value?{active:true}:{}),plan_ids:planIDs(form.plan_ids),multiplier_milli:Math.round(form.multiplier*1000),report_interval:form.interval,public_host:form.public_host,config:certificateForm.value?.buildConfig(presetForm.value?.buildConfig()||JSON.parse(form.config))||JSON.parse(form.config),exit_routing:nodeRouting(defaultExit.value,routeRules.value,globalExit.value)}}
 else body={name:form.name}
 if(props.kind==='nodes')body.public_host=publicHostForConfig(body.config,form.public_host)
 await api('/api/admin/'+props.kind+(editing.value?'/'+editing.value:''),{method:editing.value?'PATCH':'POST',body:JSON.stringify(body)});show.value=false;form.password='';message.success(props.kind==='nodes'?'已保存，等待服务器同步；ACME 模式将自动申请证书':'已保存');await load()
 }catch(e){formError.value=(e as Error).message}finally{saving.value=false}}
const columns=computed<any[]>(()=>{const edit={title:'操作',key:'actions',width:90,render:(r:any)=>h(NButton,{size:'small',quaternary:true,type:'primary',onClick:()=>open(r)},()=> '编辑')}
 if(props.kind==='users')return [{title:'用户',key:'email',minWidth:210},{title:'角色',key:'role',width:100,render:(r:any)=>h(NTag,{size:'small',bordered:false,type:r.role==='admin'?'info':'default'},()=>r.role==='admin'?'管理员':'用户')},{title:'套餐',key:'plan_id',minWidth:130,render:(r:any)=>plans.value.find(p=>p.id===r.plan_id)?.name||'未分配'},{title:'本周期已用 / 额度',key:'quota_bytes',minWidth:200,render:(r:any)=>`${bytes(r.used_bytes)} / ${bytes(r.quota_bytes)}`},{title:'下次重置 · '+(props.zone||'面板时区'),key:'next_reset_at',minWidth:190,render:(r:any)=>r.next_reset_at?cycleStamp(r.next_reset_at,props.zone||'UTC'):'尚未开通'},{title:'到期时间',key:'expires_at',minWidth:190,render:(r:any)=>r.expires_at?stamp(r.expires_at):'不限'},{title:'状态',key:'active',width:90,render:(r:any)=>h(NTag,{size:'small',bordered:false,type:r.active?'success':'default'},()=>r.active?'启用':'停用')},{title:'操作',key:'actions',width:110,fixed:'right',render:(r:any)=>h(UserActions,{user:r,plans:plans.value,me:props.me,zone:props.zone||'UTC',onEdit:open,onChanged:load})}]
 if(props.kind==='plans')return [{title:'套餐名称',key:'name',minWidth:180},{title:'额度',key:'quota_bytes',minWidth:130,render:(r:any)=>bytes(r.quota_bytes)},{title:'有效期',key:'duration_days',minWidth:110,render:(r:any)=>r.duration_days+' 天'},{title:'标价',key:'price_cents',minWidth:110,render:(r:any)=>'¥ '+(r.price_cents/100).toFixed(2)},edit]
 return [{title:'节点',key:'name',minWidth:170},{title:'协议',key:'config',minWidth:100,render:(r:any)=>r.config.protocol?.toUpperCase()},{title:'服务器',key:'machine_id',minWidth:140,render:(r:any)=>machines.value.find(m=>m.id===r.machine_id)?.name||(r.machine_id?'#'+r.machine_id:'未关联')},{title:'倍率',key:'multiplier_milli',minWidth:90,render:(r:any)=>r.multiplier_milli/1000+'×'},{title:'上报',key:'report_interval',minWidth:90,render:(r:any)=>r.report_interval+' 秒'},{title:'最近上报',key:'last_report_at',minWidth:190,render:(r:any)=>stamp(r.last_report_at)},{title:'连接器',key:'connector',minWidth:140,render:(r:any)=>{if(!r.config.connector)return '原生节点';const c=r.status?.connector;const stale=!c?.seen_at||Date.now()-Date.parse(c.seen_at)>45000;const labels:Record<string,string>={ready:r.config.connector.kind==='mtg'?'指标可用':'隧道已连接',starting:'正在连接',unhealthy:'检查失败',stopped:'已停止',queue_blocked:'上报队列阻塞'};return h(NTag,{size:'small',bordered:false,type:!stale&&c.state==='ready'?'success':'warning'},()=>stale?'状态未更新':labels[c.state]||c.state)}},{title:'可用套餐',key:'plan_ids',minWidth:150,render:(r:any)=>r.plan_ids?.length?r.plan_ids.map((id:number)=>plans.value.find(p=>p.id===id)?.name||'#'+id).join('、'):'全部套餐'},{title:'启用',key:'active',width:95,render:(r:any)=>h(NSwitch,{value:r.active,loading:toggling.value.has(r.id),'onUpdate:value':(value:boolean)=>setActive(r,value)})},{title:'操作',key:'actions',width:240,fixed:'right',render:(r:any)=>h('div',{class:'button-row'},[h(NButton,{size:'small',quaternary:true,type:'primary',onClick:()=>diagnosticNode.value=r},()=> '故障查询'),h(NButton,{size:'small',quaternary:true,type:'primary',onClick:()=>open(r)},()=> '编辑'),h(NPopconfirm,{onPositiveClick:()=>removeNode(r),positiveButtonProps:{loading:deleting.value.has(r.id)}},{trigger:()=>h(NButton,{size:'small',quaternary:true,type:'error',disabled:deleting.value.has(r.id)},()=> '删除'),default:()=>`确定删除节点“${r.name}”？节点将停用并退出同步，历史流量和账本保留。`})])}]
})
onMounted(load)
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{kind.toUpperCase()}}</span><h1>{{names[kind]}}管理</h1><p>{{descriptions[kind]}}</p></div><div class="button-row"><n-button quaternary :loading="busy" @click="load"><n-icon :component="Refresh"/></n-button><n-button v-if="kind!=='nodes'||browsingMachine!==null" type="primary" @click="open()"><template #icon><n-icon :component="Plus"/></template>新建{{names[kind]}}</n-button></div></div><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><article v-if="kind!=='nodes'||browsingMachine!==null" class="surface"><n-button v-if="kind==='nodes'" text type="primary" class="space-bottom" @click="browsingMachine=null">← 全部服务器</n-button><div class="section-heading"><div><h2>{{kind==='nodes'?serverName+' · 节点':'全部'+names[kind]}}</h2><p>{{visibleRows.length}} 条记录</p></div><n-tag :bordered="false" size="small">{{kind==='plans'?'手动分配 · 未启用支付':'数据库记录'}}</n-tag></div><n-data-table :columns="columns" :data="visibleRows" :row-key="row=>row.id" :loading="busy" :bordered="false" :scroll-x="kind==='users'?1250:kind==='nodes'?1460:600" :pagination="{pageSize:15}"/><p class="table-note">{{kind==='users'?'停用账号会停止登录与节点下发；已有用量保留。额度用于当前月度周期，按原开通日重置；修改额度不会清空已用量。':kind==='nodes'?'选择已接入的服务器，保存后自动同步节点及落地路由。配置需与服务器内核、监听端口和证书一致。':kind==='plans'?'套餐标价仅供记录，当前未启用收款。修改套餐不会自动改变已创建用户的额度。':''}}</p></article><ServerNodeCards v-else :cards="cards" :saving="layoutSaving" @select="browsingMachine=$event" @move="reorderCards"/>
 <n-modal v-model:show="show" preset="card" class="resource-modal" :title="(editing?'编辑':'新建')+names[kind]" :bordered="false"><n-alert v-if="formError" type="error" class="space-bottom">{{formError}}</n-alert><n-form label-placement="top" @submit.prevent="save">
  <n-form-item v-if="kind!=='users'" label="名称"><n-input v-model:value="form.name" :maxlength="100" placeholder="为它取个便于识别的名字"/></n-form-item>
  <template v-if="kind==='users'"><n-form-item v-if="!editing" label="邮箱"><n-input v-model:value="form.email" :input-props="{type:'email',autocomplete:'off'}"/></n-form-item><n-form-item :label="editing?'重设密码（留空则保持不变）':'密码（12–72 字节）'"><n-input v-model:value="form.password" type="password" show-password-on="click" :input-props="{autocomplete:'new-password'}"/></n-form-item><div v-if="!editing" class="form-two"><n-form-item label="角色"><n-select v-model:value="form.role" :options="[{label:'普通用户',value:'user'},{label:'管理员',value:'admin'}]"/></n-form-item><n-form-item label="套餐（可选）"><n-select v-model:value="form.plan_id" clearable :options="plans.map(x=>({label:x.name,value:x.id}))" placeholder="手动设置额度"/></n-form-item></div><p v-if="editing" class="small muted">套餐：{{plans.find(p=>p.id===form.plan_id)?.name||'未分配'}} · 邀请人 ID：{{form.inviter_id||'无'}}<br>开通日：{{form.opened_at?cycleStamp(form.opened_at,zone||'UTC'):'尚未开通'}}<br>下次重置：{{form.next_reset_at?cycleStamp(form.next_reset_at,zone||'UTC'):'尚未开通'}} · {{zone||'面板时区'}}</p><template v-if="editing||!form.plan_id"><n-form-item label="本周期额度（GiB）"><n-input-number v-model:value="form.quota_gib" :min="0" :max="1048576" :precision="2" style="width:100%"/></n-form-item><n-form-item label="到期时间（浏览器本地时间）"><div style="width:100%"><n-date-picker v-model:value="form.expiry" type="datetime" clearable style="width:100%"/><div class="button-row" style="margin-top:10px;flex-wrap:wrap"><n-button v-for="preset in [{label:'1个月',months:1},{label:'3个月',months:3},{label:'半年',months:6},{label:'1年',months:12}]" :key="preset.months" size="small" secondary @click="form.expiry=extendExpiry(form.expiry,preset.months)">{{preset.label}}</n-button></div><p class="small muted" style="margin:8px 0 0">从当前到期时间顺延；已到期或未设置则从现在计算，短月份取月末。保存后生效。</p></div></n-form-item></template><n-form-item v-if="editing" label="账号启用"><n-switch v-model:value="form.active"/></n-form-item></template>
  <template v-if="kind==='plans'"><div class="form-two"><n-form-item label="额度（GiB）"><n-input-number v-model:value="form.quota_gib" :min="0" :max="1048576"/></n-form-item><n-form-item label="有效天数"><n-input-number v-model:value="form.days" :min="1" :max="3650" :precision="0"/></n-form-item></div><n-form-item label="标价（元，仅记录）"><n-input-number v-model:value="form.price" :min="0" :max="1000000" :precision="2"/></n-form-item></template>
  <template v-if="kind==='nodes'"><n-alert v-if="!machines.length" type="warning" class="space-bottom">请先到“服务器管理”添加服务器并执行安装命令，再为节点选择服务器。</n-alert><ProtocolPreset ref="presetForm" :config="form.config" :editing="!!editing" :machine-id="form.machine_id" @config="form.config=$event"/><div class="form-two"><n-form-item label="归属服务器（必选）"><n-select v-model:value="form.machine_id" :options="machines.map(x=>({label:x.name,value:x.id}))" placeholder="选择已安装的服务器"/></n-form-item><n-form-item label="计费倍率"><n-input-number v-model:value="form.multiplier" :min="0.001" :max="100" :precision="3"/></n-form-item><n-form-item label="上报间隔（秒）"><n-input-number v-model:value="form.interval" :min="10" :max="3600" :precision="0"/></n-form-item></div><n-form-item v-if="!usesTunnel" label="对外域名或 IP（用于订阅）"><n-input v-model:value="form.public_host" placeholder="node.example.com，不带协议前缀"/></n-form-item><p v-else class="small muted">CF Tunnel 订阅域名使用上方服务器名称，保存时保持一致，不使用节点机 IP。</p><section v-if="form.machine_id&&!usesTunnel" class="machine-addresses"><template v-if="publicAddresses.length"><p class="small muted">来源：节点机物理网卡（排除 WARP） · {{stamp(selectedMachine?.status?.public_addresses?.detected_at)}}</p><p v-if="!automaticMachineAddress(selectedMachine?.status)" class="small muted">地址记录已过期，仅供手动选择；不会自动填入。</p><div class="address-choices"><n-button v-for="address in publicAddresses" :key="address" size="small" secondary @click="fillAddress(address)">填入 {{address.includes(':')?'IPv6':'IPv4'}}：{{address}}</n-button></div><p class="small muted">选择服务器时优先填入 IPv4，其次 IPv6。手动填写的域名或 IP 会保留；点击地址按钮可替换。</p></template><n-alert v-else type="warning" class="space-bottom">尚未检测到真实公网地址，请手动填写或升级节点。</n-alert></section><n-form-item label="可用套餐（多选，留空为不限制）"><n-select v-model:value="form.plan_ids" multiple clearable :options="plans.map(p=>({label:p.name,value:p.id}))" placeholder="全部符合使用条件的账号"/></n-form-item><p class="small muted">管理员也遵守套餐范围。无套餐账号只能使用不限制套餐的节点。启用状态在节点列表直接切换。</p><NodeCertificate ref="certificateForm" :config="form.config"/><n-form-item label="高级节点配置（JSON，可修改）"><n-input v-model:value="form.config" type="textarea" :autosize="{minRows:8,maxRows:16}" class="code-input"/></n-form-item><n-alert type="info">一键生成后仍可修改参数及 JSON。TLS 证书通过上方表单自动下发；私密配置需要部署 LUMA_MASTER_KEY。H3 和 Hysteria2 需要开放 UDP 端口。</n-alert><NodeRouting v-model:global-exit="globalExit" v-model:default-exit="defaultExit" v-model:rules="routeRules" :exits="exits" :machine-id="form.machine_id" :kernel-type="kernelType"/></template>
 </n-form><template #footer><div class="modal-footer"><n-button @click="show=false">取消</n-button><n-button type="primary" :loading="saving" @click="save">保存{{names[kind]}}</n-button></div></template></n-modal>

 <NodeDiagnostics v-if="diagnosticNode" :node="diagnosticNode" @close="diagnosticNode=null"/>
</template>
<style scoped>.machine-addresses{margin:-8px 0 22px}.address-choices{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.address-choices :deep(.n-button){height:auto;min-height:30px;padding:6px 10px;max-width:100%}.address-choices :deep(.n-button__content){white-space:normal;overflow-wrap:anywhere;text-align:left}@media(max-width:640px){.page-heading{flex-direction:column;align-items:stretch}.page-heading>.button-row{flex-wrap:wrap}}</style>
